using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;
using BenchmarkDotNet.Jobs;
using TextAnalysis;

[SimpleJob(RuntimeMoniker.Net90)]
[SimpleJob(RuntimeMoniker.Net100)]
[MemoryDiagnoser]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    [GlobalSetup]
    public void Setup()
    {
        // A reasonably sized sample text for benchmarking
        var words = new List<string>();
        var rng = new Random(42);
        string[] sampleWords = { "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
            "benchmark", "performance", "analysis", "framework", "computing", "algorithm",
            "structure", "optimization", "parallel", "sequential", "iteration", "collection" };
        for (int i = 0; i < 10_000; i++)
            words.Add(sampleWords[rng.Next(sampleWords.Length)]);
        _analyzer = new TextAnalyzer(string.Join(" ", words));
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

BenchmarkRunner.Run<TextAnalyzerBenchmarks>(args: args);

